/**
 * Reference IDs (docs/portals/README.md §8): `PREFIX-XXXXXXXX`, eight Crockford base32
 * characters generated by the database. Shared by server and client code.
 *
 * A reference ID identifies; it never authorizes. Every lookup still applies the actor's scope.
 */

export const REFERENCE_ENTITIES = {
  USR: { label: "User", path: "/users" },
  AGT: { label: "Agent", path: "/agents" },
  ADM: { label: "Admin", path: "/admins" },
  SADM: { label: "SuperAdmin", path: "/admins" },
  ORG: { label: "Organization", path: "/organizations" },
  PRP: { label: "Property", path: "/properties" },
  LST: { label: "Listing", path: "/properties" },
  PROJ: { label: "Project", path: null },
  LEAD: { label: "Lead", path: "/leads" },
  VIS: { label: "Visit", path: "/visits" },
  VER: { label: "Review case", path: "/approvals" },
  RPT: { label: "Report", path: "/reports" },
  INV: { label: "Invitation", path: "/admins" },
  CON: { label: "Contact", path: "/contacts" },
  DOC: { label: "Document", path: null },
  HST: { label: "Host", path: "/hosts" },
  BKG: { label: "Booking", path: "/bookings" },
  TKT: { label: "Contact message", path: "/inbox" },
  MSG: { label: "Conversation", path: "/messages" },
  LGL: { label: "Legal verification request", path: "/legal-requests" },
  COM: { label: "Commission charge", path: "/commissions" },
  SUB: { label: "Subscription", path: "/subscriptions" },
} as const;

export type ReferencePrefix = keyof typeof REFERENCE_ENTITIES;

const BODY = "[0-9A-HJKMNP-TV-Z]{8}";
const PATTERN = new RegExp(`^(${Object.keys(REFERENCE_ENTITIES).join("|")})-(${BODY})$`);

/** Normalises what people type: case, surrounding space, and the letters Crockford reads as digits. */
export function normalizeReferenceId(input: string): string {
  const trimmed = input.trim().toUpperCase();
  const dash = trimmed.indexOf("-");
  if (dash < 0) return trimmed;
  const body = trimmed
    .slice(dash + 1)
    .replace(/O/g, "0")
    .replace(/[IL]/g, "1");
  return `${trimmed.slice(0, dash)}-${body}`;
}

export function parseReferenceId(input: string): { prefix: ReferencePrefix; value: string } | null {
  const value = normalizeReferenceId(input);
  const match = PATTERN.exec(value);
  return match ? { prefix: match[1] as ReferencePrefix, value } : null;
}

export function isReferenceId(input: unknown, prefix?: ReferencePrefix): input is string {
  if (typeof input !== "string") return false;
  const parsed = PATTERN.exec(input);
  return parsed !== null && (prefix === undefined || parsed[1] === prefix);
}
